package com.bplus.share;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.media.MediaRecorder;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;
/** Foreground hold-to-record. Release sends, horizontal slide/cancel/lifecycle stop discards. */
public final class VoiceRecorder{
 public interface Send{void send(Uri uri,String name,long size);}
 private EditText input;private PopupWindow feedback;private TextView timer;private RecordingWave wave;private final Handler handler=new Handler();private final Runnable meter=new Runnable(){public void run(){if(recorder==null)return;try{wave.sample(recorder.getMaxAmplitude());if(!cancelled)timer.setText(VoicePlayer.time((int)(SystemClock.elapsedRealtime()-started)));handler.postDelayed(this,80);}catch(Exception ignored){}}};private final Activity a;private final Send send;private MediaRecorder recorder;private File file;private long started;private float down;private boolean cancelled;private final TextView button;
 public VoiceRecorder(Activity a,TextView button,EditText input,Send send){this(a,button,send);this.input=input;}
 public VoiceRecorder(Activity a,TextView button,Send send){this.a=a;this.button=button;this.send=send;button.setContentDescription(a.getString(R.string.voice_hold));button.setOnTouchListener((v,e)->touch(e));}
 private boolean touch(MotionEvent e){if(recorder==null&&input!=null&&input.getText().length()>0)return false;int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){down=e.getRawX();cancelled=false;if(a.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){new AppDialog(a).setTitle(R.string.voice_title).setMessage(R.string.voice_permission_note).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.voice_allow,(d,n)->a.requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},822)).show();return true;}start();return true;}if(action==MotionEvent.ACTION_MOVE&&recorder!=null&&VoiceRules.cancel(down,e.getRawX(),Ui.dp(a,80))){cancelled=true;button.setText("✕");if(timer!=null)timer.setText(R.string.voice_cancel_release);}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){finish(cancelled||action==MotionEvent.ACTION_CANCEL);return true;}return true;}
 private void start(){try{File dir=new File(a.getFilesDir(),"voice");if(!dir.exists()&&!dir.mkdirs())throw new IOException();file=new File(dir,"voice-"+java.util.UUID.randomUUID()+".m4a");recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioSamplingRate(44100);recorder.setAudioEncodingBitRate(64000);recorder.setOutputFile(file.getAbsolutePath());recorder.setMaxDuration(300000);recorder.setOnInfoListener((r,what,extra)->{if(what==MediaRecorder.MEDIA_RECORDER_INFO_MAX_DURATION_REACHED){finish(true);Toast.makeText(a,R.string.voice_limit,1).show();}});recorder.prepare();recorder.start();started=SystemClock.elapsedRealtime();showFeedback();button.setText("●");button.setTextColor(0xffff6565);Toast.makeText(a,R.string.voice_recording,Toast.LENGTH_LONG).show();button.getParent().requestDisallowInterceptTouchEvent(true);}catch(Exception e){finish(true);new AppDialog(a).setTitle(R.string.voice_title).setMessage(R.string.voice_failed).setPositiveButton(android.R.string.ok,null).show();}}
 private void showFeedback(){LinearLayout panel=Ui.col(a);panel.setBackground(Ui.roundBorder(Ui.card,Ui.border,18,a));Ui.pad(panel,16,12,16,12,a);LinearLayout top=Ui.row(a);TextView dot=Ui.t(a,"●",18,0xffff6565,App.cairoB);top.addView(dot,Ui.lp(Ui.dp(a,28),-2));timer=Ui.t(a,"0:00",18,Ui.text,App.cairoB);top.addView(timer,Ui.lpw(1));panel.addView(top);wave=new RecordingWave(a);panel.addView(wave,Ui.lp(-1,Ui.dp(a,48)));panel.addView(Ui.t(a,a.getString(R.string.voice_slide_hint),12,Ui.dim,App.cairoSB));feedback=new PopupWindow(panel,Math.min(a.getResources().getDisplayMetrics().widthPixels-Ui.dp(a,28),Ui.dp(a,400)),-2,false);feedback.setBackgroundDrawable(Ui.round(Ui.card,18,a));feedback.setElevation(Ui.dp(a,12));feedback.setTouchable(false);feedback.showAtLocation(button,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL,0,Ui.dp(a,92));handler.post(meter);}
 public void cancel(){finish(true);}
 private void finish(boolean discard){handler.removeCallbacks(meter);if(feedback!=null){feedback.dismiss();feedback=null;}if(recorder==null)return;long duration=SystemClock.elapsedRealtime()-started;try{recorder.stop();}catch(Exception e){discard=true;}try{recorder.release();}catch(Exception ignored){}recorder=null;button.setText(input!=null&&input.getText().length()>0?"➤":"🎙");button.setTextColor(Ui.accent);button.getParent().requestDisallowInterceptTouchEvent(false);if(file==null||!VoiceRules.send(discard,duration,file.length())){if(file!=null)file.delete();return;}Uri uri=Uri.parse("content://"+a.getPackageName()+".files/voice/"+Uri.encode(file.getName()));send.send(uri,file.getName(),file.length());}
}
